const TAGALAG_BISIG_RECOMMENDATIONS: RecommendedLocation[] = [
  { id: "tagalag-terminal", name: "Tagalag Terminal", full: "Main Road, Tagalag, Valenzuela City", lat: 14.7294, lng: 120.9349 },
