      read: false,
      priority: 'normal'
    },
    {
      id: '3',
      type: 'info',
      icon: 'info',
      title: 'Weekly Earnings Summary',
      message: 'You earned ₱2,850 this week. Great job!',
      time: '2 hours ago',
      read: true,
      priority: 'normal'
    },
    {
      id: '4',
      type: 'message',
