          </h2>

          <div className="space-y-4">
            {/* TODA Plate Number */}
            <div>
              <label className="text-xs font-semibold text-[#64748B] uppercase tracking-wide mb-2 block">
                TODA Plate Number
              </label>
              {isEditing ? (
                <Input
                  value={formData.todaPlate}
                  onChange={(e) => setFormData({ ...formData, todaPlate: e.target.value })}
