                  onChange={(e) => setFormData({ ...formData, dropoffLocation: e.target.value })}
                  className="w-full"
                  placeholder="e.g., Barangay Hall, Tagalog"
                  required
                />
              ) : (
                <div className="flex items-start gap-2">
                  <MapPin className="w-4 h-4 text-[#10B981] mt-1 flex-shrink-0" />
