          }}
          className="w-full bg-[#121212] hover:bg-[#2a2a2a] text-white font-bold uppercase py-4 rounded-lg flex items-center justify-center gap-2 shadow-md"
        >
          <LogOut className="w-5 h-5" />
          Sign Out
        </Button>

        {/* Bottom spacing for safe area */}
        <div className="h-8" />
      </div>
    </div>
  );
}

